-- Phase 3 — violations (brief §7.2, §7.3). Partial indexes are raw SQL (ADR-002); the last index is Prisma-generated.

-- At most one ID-card photo per violation. The service checks the limit under a row lock;
-- this index is the last line of defence.
CREATE UNIQUE INDEX violation_files_one_id_card_uq
  ON violation_files (violation_id)
  WHERE kind = 'ID_CARD';

-- Retention job and photo-limit counts: violation files by entity and kind.
CREATE INDEX files_violation_kind_idx
  ON files (entity_id, kind)
  WHERE entity_type = 'violation';

-- Generated by prisma migrate diff (schema.prisma @@index([memberId, capturedAt])):
-- CreateIndex
CREATE INDEX "violations_member_id_captured_at_idx" ON "violations"("member_id", "captured_at");
